using System.Collections.Concurrent;using CatalogService.Models;namespace CatalogService.Services;public sealed class SubjectStore{private readonly ConcurrentDictionary<int,Subject> _items=new();private int _nextId=2;public SubjectStore(){_items[1]=new(1,"ENG","English Language",true);_items[2]=new(2,"MAT","Mathematics",true);}public IReadOnlyCollection<Subject> GetAll()=>_items.Values.OrderBy(x=>x.Id).ToArray();public Subject? Get(int id)=>_items.GetValueOrDefault(id);public Subject Add(CreateSubjectRequest r){var id=Interlocked.Increment(ref _nextId);var s=new Subject(id,r.Code.Trim().ToUpperInvariant(),r.Name.Trim(),r.Active);_items[id]=s;return s;}public Subject? Update(int id,UpdateSubjectRequest r){if(!_items.ContainsKey(id))return null;var s=new Subject(id,r.Code.Trim().ToUpperInvariant(),r.Name.Trim(),r.Active);_items[id]=s;return s;}public bool Delete(int id)=>_items.TryRemove(id,out _);}